"-400\" y=\"-100\" width=\"2400\" height=\"1200\" fill=\"url(#scan)\" opacity=\"0.15\"/>\n<rect x=\"-400\" y=\"-100\" width=\"2400\" height=\"1200\" fill=\"url(#vig)\"/>\n</svg>"

// The app redraws the backdrop now and then, which restarts every CSS animation from
// zero. Each start delay becomes a marker, and every draw shifts it back by the time
// the scene has been running, so a redraw resumes each loop where it was.
const BORN = Date.now()
const TIME = /(?<![\w(.])-?\d*\.?\d+s\b/g
const SCENE_TEMPLATE = SCENE
  .replace(/animation:([^;]*);/g, (rule, body: string) => {
    if (!body.includes('infinite')) return rule
    const times = body.match(TIME) ?? []
    if (times.length >= 2) {
      let seen = 0
      return `animation:${body.replace(TIME, t => (++seen === 2 ? `@@D${t.slice(0, -1)}@@` : t))};`
    }
    return `animation:${body} @@D0@@;`
  })
  .replace(/animation-delay:(-?\d*\.?\d+)s/g, 'animation-delay:@@D$1@@')

const sceneNow = () => {
  const ran = (Date.now() - BORN) / 1000
  return SCENE_TEMPLATE.replace(/@@D(-?\d*\.?\d+)@@/g, (_, d: string) => `${(Number(d) - ran).toFixed(3)}s`)
}

const LOOK: ThemeSetArgs = {
  colors: theme,
  backdrop: { scene: 'agent-playground', glass: { blur: 0, tint: '#0b0506', opacity: 0.3 } },
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))

    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }
    const set = await $.theme.set(LOOK)

    if (set.isDrawn) {
      $.ui.toast('Agent playground theme applied')
    } else {
      $.ui.status(`Agent playground not drawn: ${set.reason}`)
      $.ui.toast(`Agent playground not drawn: ${set.reason}`)
    }

    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.surface !== 'desktop' && e.surface !== 'mobile') {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)

    return <Svg source={sceneNow()} alt="A developer in a red hoodie tossing a ball to pixel Claude agents on a red neon grid, binary rain at the edges, a German flag on the right" isInteractive />
  })
}
